<?php
require_once 'config.php'; $pageTitle='Explore opportunities';
$q=trim($_GET['q']??''); $location=trim($_GET['location']??''); $category=trim($_GET['category']??'');
$sql="SELECT j.*, u.name AS poster_name FROM jobs j JOIN users u ON u.id=j.posted_by WHERE j.status='published' AND (j.deadline IS NULL OR j.deadline >= CURDATE())"; $params=[];
if($q!==''){ $sql.=" AND (j.title LIKE ? OR j.company_name LIKE ? OR j.description LIKE ? OR j.category LIKE ?)"; $like="%$q%"; array_push($params,$like,$like,$like,$like); }
if($location!==''){ $sql.=" AND j.location LIKE ?"; $params[]="%$location%"; }
if($category!==''){ $sql.=" AND j.category = ?"; $params[]=$category; }
$sql.=" ORDER BY j.created_at DESC"; $stmt=$pdo->prepare($sql); $stmt->execute($params); $jobs=$stmt->fetchAll();
$categories=$pdo->query("SELECT DISTINCT category FROM jobs WHERE status='published' ORDER BY category")->fetchAll(PDO::FETCH_COLUMN);
require 'includes/header.php'; ?>
<section class="page-hero compact-hero"><div class="eyebrow"><span class="eyebrow-dot"></span> FIND YOUR FIT</div><h1>Good things start<br>with <span class="text-accent">a search.</span></h1><p>Find internships and early-career roles that match where you want to go.</p><form class="listing-search" method="get"><label class="search-field"><span>⌕</span><input name="q" value="<?= e($q) ?>" placeholder="Job title, company, or skill" aria-label="Search jobs"></label><label class="search-field"><span>⌖</span><input name="location" value="<?= e($location) ?>" placeholder="City or remote" aria-label="Filter by location"></label><button class="button button-primary" type="submit">Search jobs ↗</button></form></section>
<section class="section listings-section"><div class="listing-heading"><div><h2>Explore opportunities <span class="count-pill"><?= count($jobs) ?></span></h2><p>Thoughtful beginnings for ambitious people.</p></div><form method="get" class="category-filter"><input type="hidden" name="q" value="<?= e($q) ?>"><input type="hidden" name="location" value="<?= e($location) ?>"><label for="category">Category</label><select id="category" name="category" onchange="this.form.submit()"><option value="">All categories</option><?php foreach($categories as $cat): ?><option value="<?= e($cat) ?>" <?= $category===$cat?'selected':'' ?>><?= e($cat) ?></option><?php endforeach; ?></select></form></div>
<?php if($jobs): ?><div class="job-list"><?php foreach($jobs as $i=>$job): ?><article class="job-row reveal"><div class="company-logo logo-<?= ($i%4)+1 ?>"><?= e(initials($job['company_name'])) ?></div><div class="job-row-main"><div class="job-row-title"><h3><a href="job.php?id=<?= (int)$job['id'] ?>"><?= e($job['title']) ?></a></h3><span class="job-type"><?= e($job['category']) ?></span></div><p><?= e($job['company_name']) ?></p><div class="job-meta"><span>⌖ <?= e($job['location']) ?></span><span>◷ <?= $job['deadline'] ? 'Deadline '.date('M j, Y',strtotime($job['deadline'])) : 'Open until filled' ?></span></div></div><a class="button button-secondary row-apply" href="job.php?id=<?= (int)$job['id'] ?>">View role <span>↗</span></a></article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><div class="empty-icon">⌕</div><h3>No matches just yet</h3><p>Try a different keyword, broaden your location, or clear the category filter.</p><a class="button button-secondary" href="jobs.php">Clear all filters</a></div><?php endif; ?></section>
<?php require 'includes/footer.php'; ?>
